import{_ as o,r as e,o as p,c as i,e as a,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Application - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":4,"title":"Binding To The Container","slug":"binding-to-the-container","link":"#binding-to-the-container","children":[]},{"level":4,"title":"Resolving From The container","slug":"resolving-from-the-container","link":"#resolving-from-the-container","children":[]},{"level":4,"title":"Binding a \\"shared\\" type into the container","slug":"binding-a-shared-type-into-the-container","link":"#binding-a-shared-type-into-the-container","children":[]},{"level":4,"title":"Binding an existing instance into the container","slug":"binding-an-existing-instance-into-the-container","link":"#binding-an-existing-instance-into-the-container","children":[]},{"level":4,"title":"Binding an interface to an implementation","slug":"binding-an-interface-to-an-implementation","link":"#binding-an-interface-to-an-implementation","children":[]},{"level":3,"title":"Where to Register Bindings","slug":"where-to-register-bindings","link":"#where-to-register-bindings","children":[]},{"level":2,"title":"Service Providers","slug":"service-providers","link":"#service-providers","children":[{"level":4,"title":"Defining a Service Provider","slug":"defining-a-service-provider","link":"#defining-a-service-provider","children":[]},{"level":4,"title":"Registering a Service Provider at Runtime","slug":"registering-a-service-provider-at-runtime","link":"#registering-a-service-provider-at-runtime","children":[]}]},{"level":2,"title":"Application Events","slug":"application-events","link":"#application-events","children":[{"level":4,"title":"Request Events","slug":"request-events","link":"#request-events","children":[]},{"level":4,"title":"Container Events","slug":"container-events","link":"#container-events","children":[]}]},{"level":2,"title":"Application Helpers","slug":"application-helpers","link":"#application-helpers","children":[{"level":4,"title":"Finding the Application Environment","slug":"finding-the-application-environment","link":"#finding-the-application-environment","children":[]},{"level":4,"title":"Determine the Execution Context","slug":"determine-the-execution-context","link":"#determine-the-execution-context","children":[]}]}],"relativePath":"4.x/extend/services/application.md","filePath":"4.x/extend/services/application.md"}'),l={name:"4.x/extend/services/application.md"};function u(d,n,h,k,g,v){const s=e("pre-heading"),t=e("post-heading");return p(),i("div",null,[a(s),n[0]||(n[0]=c("h1",null,"Application",-1)),a(t),n[1]||(n[1]=r(`<p>The inversion of control (IoC) container is a tool for managing class dependencies. Dependency injection is a method of removing hard-coded class dependencies. Instead, the dependencies are injected at run-time, allowing for greater flexibility as dependency implementations may be swapped easily.</p><h4 id="binding-to-the-container"><a href="#binding-to-the-container" class="header-anchor">#</a> Binding To The Container</h4><p>There are two ways the IoC container can resolve dependencies: via Closure callbacks or automatic resolution. First, we&#39;ll explore Closure callbacks. First, a &quot;type&quot; may be bound into the container.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="resolving-from-the-container"><a href="#resolving-from-the-container" class="header-anchor">#</a> Resolving From The container</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When the <code>App::make</code> method is called, the Closure callback is executed and the result is returned.</p><h4 id="binding-a-shared-type-into-the-container"><a href="#binding-a-shared-type-into-the-container" class="header-anchor">#</a> Binding a &quot;shared&quot; type into the container</h4><p>Sometimes you may wish to bind something into the container that should only be resolved once, and the same instance should be returned on subsequent calls into the container:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">singleton</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="binding-an-existing-instance-into-the-container"><a href="#binding-an-existing-instance-into-the-container" class="header-anchor">#</a> Binding an existing instance into the container</h4><p>You may also bind an existing object instance into the container using the <code>instance</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$foo</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token variable">$foo</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="binding-an-interface-to-an-implementation"><a href="#binding-an-interface-to-an-implementation" class="header-anchor">#</a> Binding an interface to an implementation</h4><p>In some cases, a class may depend on an interface implementation, not a &quot;concrete type&quot;. When this is the case, the <code>App::bind</code> method must be used to inform the container which interface implementation to inject:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;DbUserRepository&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Now consider the following code:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Since we have bound the <code>UserRepositoryInterface</code> to a concrete type, the <code>DbUserRepository</code> will automatically be injected into this controller when it is created.</p><h3 id="where-to-register-bindings"><a href="#where-to-register-bindings" class="header-anchor">#</a> Where to Register Bindings</h3><p>IoC bindings, like <a href="./event.html">event handlers</a>, generally fall under the category of &quot;bootstrap code&quot;. In other words, they prepare your application to actually handle requests, and usually need to be executed before a route or controller is actually called. The most common place is the <code>boot</code> method of a <a href="./../extending.html">plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place IoC registration logic.</p><h2 id="service-providers"><a href="#service-providers" class="header-anchor">#</a> Service Providers</h2><p>Service providers are a great way to create libraries and perform group related IoC registrations in a single location. Within a service provider, you might register a custom authentication driver, register your application&#39;s repository classes with the IoC container, or even setup a custom Artisan command.</p><p>In fact, <a href="./../system/plugins.html">plugin registration files</a> inherit service providers and most of the core components include service providers. All of the registered service providers for your application are listed in the <code>providers</code> array of the <code>config/app.php</code> configuration file.</p><h4 id="defining-a-service-provider"><a href="#defining-a-service-provider" class="header-anchor">#</a> Defining a Service Provider</h4><p>To create a service provider, simply extend the <code>October\\Rain\\Support\\ServiceProvider</code> class and define a <code>register</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>ServiceProvider</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FooServiceProvider</span> <span class="token keyword">extends</span> <span class="token class-name">ServiceProvider</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">app</span><span class="token operator">-&gt;</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Note that in the <code>register</code> method, the application IoC container is available to you via the <code>$this-&gt;app</code> property. Once you have created a provider and are ready to register it with your application, simply add it to the <code>providers</code> array in your <code>app</code> configuration file.</p><h4 id="registering-a-service-provider-at-runtime"><a href="#registering-a-service-provider-at-runtime" class="header-anchor">#</a> Registering a Service Provider at Runtime</h4><p>You may also register a service provider at run-time using the <code>App::register</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FooServiceProvider&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="application-events"><a href="#application-events" class="header-anchor">#</a> Application Events</h2><h4 id="request-events"><a href="#request-events" class="header-anchor">#</a> Request Events</h4><p>You can register special events before a request is routed using the <code>before</code> and <code>after</code> methods.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Code to execute before the request is routed</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Code to execute after the request is routed</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="container-events"><a href="#container-events" class="header-anchor">#</a> Container Events</h4><p>The service container fires an event each time it resolves an object. You may listen to this event using the <code>resolving</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$object</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Called when container resolves object of any type...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Called when container resolves objects using hint &quot;foo&quot;...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme\\Blog\\Classes\\FooBar&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Called when container resolves objects of type &quot;FooBar&quot;...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>As you can see, the object being resolved will be passed to the callback, allowing you to set any additional properties on the object before it is given to its consumer.</p><h2 id="application-helpers"><a href="#application-helpers" class="header-anchor">#</a> Application Helpers</h2><h4 id="finding-the-application-environment"><a href="#finding-the-application-environment" class="header-anchor">#</a> Finding the Application Environment</h4><p>You may use the <code>environment</code> method to discover the application environment as determined by the <a href="./../../setup/configuration.html">environment configuration</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// production</span>
<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">environment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="determine-the-execution-context"><a href="#determine-the-execution-context" class="header-anchor">#</a> Determine the Execution Context</h4><p>It is possible to know if the current request is being performed in the administrative back-end area using the <code>runningInBackend</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInBackend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also use the <code>runningInConsole</code> method to check if the executing code is taking place inside the <a href="./../console-commands.html">command line interface</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInConsole</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,48))])}const b=o(l,[["render",u]]);export{f as __pageData,b as default};
